/**
 * The agent's own passkeys (INFRA-585).
 *
 * A passkey the agent enrolls on a site is generated by the tab's virtual authenticator
 * (see TabManager.runPasskeyCeremony) and kept here, in chrome.storage.local — restricted to
 * trusted contexts at startup (storage-privacy.ts), the same place that holds the pairing
 * token. The private key never leaves the browser: it is not sent to the MCP server, so it
 * never reaches tool results, logs or a transcript.
 *
 * WebAuthn binds a credential to its rpId, which must be the page's host or a registrable
 * suffix of it: a credential enrolled on accounts.shopify.com is only ever offered to a tab
 * on that host (or a subdomain), whatever page asks.
 */

const STORAGE_KEY = 'agent_jake_passkeys';

export interface StoredPasskey {
  credentialId: string;
  rpId: string;
  /** Base64 PKCS#8, as CDP WebAuthn.getCredentials returns it. */
  privateKey: string;
  userHandle?: string;
  signCount: number;
  isResidentCredential: boolean;
  enrolledAt: string;
}

/** What a tool result may say about a passkey: never the key, never the handle. */
export interface PasskeySummary {
  rpId: string;
  enrolledAt: string;
}

async function readAll(): Promise<StoredPasskey[]> {
  const stored = (await chrome.storage.local.get(STORAGE_KEY))[STORAGE_KEY];
  return Array.isArray(stored) ? (stored as StoredPasskey[]) : [];
}

export function rpIdMatchesHost(rpId: string, host: string): boolean {
  return host === rpId || host.endsWith(`.${rpId}`);
}

export async function passkeysForHost(host: string): Promise<StoredPasskey[]> {
  return (await readAll()).filter((p) => rpIdMatchesHost(p.rpId, host));
}

/** Adds new credentials and refreshes the sign count of known ones (matched by credentialId). */
export async function savePasskeys(passkeys: StoredPasskey[]): Promise<void> {
  if (!passkeys.length) return;
  const byId = new Map((await readAll()).map((p) => [p.credentialId, p]));
  for (const p of passkeys) {
    const known = byId.get(p.credentialId);
    byId.set(p.credentialId, known ? { ...known, signCount: Math.max(known.signCount, p.signCount) } : p);
  }
  await chrome.storage.local.set({ [STORAGE_KEY]: [...byId.values()] });
}

export function summarize(passkeys: StoredPasskey[]): PasskeySummary[] {
  return passkeys.map(({ rpId, enrolledAt }) => ({ rpId, enrolledAt }));
}
